import{_ as t,o,c as a,a2 as r}from"./chunks/framework.B8TleWq7.js";const u=JSON.parse('{"title":"Connect Roblox Studio","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/connect-studio.md","filePath":"getting-started/connect-studio.md"}'),i={name:"getting-started/connect-studio.md"};function n(c,e,d,s,l,p){return o(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="connect-roblox-studio" tabindex="-1">Connect Roblox Studio <a class="header-anchor" href="#connect-roblox-studio" aria-label="Permalink to &quot;Connect Roblox Studio&quot;">​</a></h1><p>Keel uses Studio&#39;s built-in <strong>Script Sync</strong>: the code lives in files under <code>src/</code>, and Studio keeps the scripts in step with them. Script Sync can only sync <strong>Folders</strong>, so a game has six root Folders.</p><p>Studio cannot script the Script Sync connect, so there is one manual step per Folder. The <strong>Keel Setup plugin</strong> does everything around it.</p><h2 id="_1-install-the-keel-setup-plugin-once-per-computer" tabindex="-1">1. Install the Keel Setup plugin (once per computer) <a class="header-anchor" href="#_1-install-the-keel-setup-plugin-once-per-computer" aria-label="Permalink to &quot;1. Install the Keel Setup plugin (once per computer)&quot;">​</a></h2><p>Every game has the plugin at <code>tools/KeelSetup.lua</code>.</p><ol><li>In Studio, open the <strong>Plugins</strong> tab and click <strong>Plugins Folder</strong>.</li><li>Copy <code>tools/KeelSetup.lua</code> into that folder (on Windows, <code>%LOCALAPPDATA%\\Roblox\\Plugins</code>).</li><li>Restart Studio. A <strong>Keel</strong> toolbar with a <strong>Keel Setup</strong> button appears in the Plugins tab.</li></ol><p>To update the plugin after a Keel update, copy the file again.</p><h2 id="_2-press-keel-setup" tabindex="-1">2. Press Keel Setup <a class="header-anchor" href="#_2-press-keel-setup" aria-label="Permalink to &quot;2. Press Keel Setup&quot;">​</a></h2><p>Open your place and click <strong>Keel Setup</strong>. It:</p><ul><li>creates any missing Folder from the table below (an existing Folder is never touched);</li><li>creates the optional place attributes with their defaults, only where they have no value yet (<code>FastSpawn</code>, <code>LogOff</code>, <code>Version</code> on <code>ReplicatedStorage</code>; <code>FreshData</code>, <code>DataVersion</code> on <code>ServerScriptService</code>);</li><li>opens a checklist that shows which Folders exist and the disk folder each one connects to.</li></ul><p>It is safe to press twice, and the change can be undone with Ctrl+Z.</p><h2 id="_3-connect-each-folder-once-per-place" tabindex="-1">3. Connect each Folder (once per place) <a class="header-anchor" href="#_3-connect-each-folder-once-per-place" aria-label="Permalink to &quot;3. Connect each Folder (once per place)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Disk folder</th><th>Studio Folder</th><th>Holds</th></tr></thead><tbody><tr><td><code>src/ReplicatedStorage/Keel/</code></td><td><code>ReplicatedStorage.Keel</code></td><td>Keel, shared parts</td></tr><tr><td><code>src/ReplicatedStorage/Shared/</code></td><td><code>ReplicatedStorage.Shared</code></td><td>this game&#39;s shared code: Defs, the Net list</td></tr><tr><td><code>src/ServerScriptService/KeelServer/</code></td><td><code>ServerScriptService.KeelServer</code></td><td>Keel, server-only parts</td></tr><tr><td><code>src/ServerScriptService/Server/</code></td><td><code>ServerScriptService.Server</code></td><td>this game&#39;s server code</td></tr><tr><td><code>src/ReplicatedFirst/Client/</code></td><td><code>ReplicatedFirst.Client</code></td><td>all of this game&#39;s client code</td></tr><tr><td><code>src/StarterPlayer/StarterPlayerScripts/Boot/</code></td><td><code>StarterPlayer.StarterPlayerScripts.Boot</code></td><td>only <code>Boot.local.luau</code></td></tr></tbody></table><p>For each row:</p><ol><li>Right-click the Folder, then <strong>Script Sync</strong>, then <strong>Sync with Directory</strong>.</li><li>Pick the matching disk folder and choose <strong>Keep Disk</strong> (the files win).</li><li>Turn auto-resume on.</li></ol><p>After that, everything inside a root syncs both ways on its own.</p><div class="info custom-block"><p class="custom-block-title">Note</p><p>The connections belong to the place on your computer. They are not saved inside the place file, so copying or re-saving a place does not carry them: a template place file with the Folders already connected was tried, and the scripts appeared but the connections did not. Do the connects once for each place you open on a new computer.</p></div><h2 id="doing-it-without-the-plugin" tabindex="-1">Doing it without the plugin <a class="header-anchor" href="#doing-it-without-the-plugin" aria-label="Permalink to &quot;Doing it without the plugin&quot;">​</a></h2><p>The plugin only saves you creating the Folders and attributes by hand. To skip it, create a <strong>Folder</strong> with each name from the table under its service in Studio, then do step 3.</p><h2 id="file-names-decide-the-script-type" tabindex="-1">File names decide the script type <a class="header-anchor" href="#file-names-decide-the-script-type" aria-label="Permalink to &quot;File names decide the script type&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Becomes</th></tr></thead><tbody><tr><td><code>Name.luau</code></td><td>ModuleScript</td></tr><tr><td><code>Name.server.luau</code></td><td>Script</td></tr><tr><td><code>Name.local.luau</code></td><td>LocalScript</td></tr><tr><td><code>Name/init.luau</code></td><td>ModuleScript with children</td></tr></tbody></table><h2 id="press-play" tabindex="-1">Press Play <a class="header-anchor" href="#press-play" aria-label="Permalink to &quot;Press Play&quot;">​</a></h2><p>Start a playtest. The Output window should show:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Loader] Server booted …</span></span>
<span class="line"><span>[Loader] Client booted …</span></span></code></pre></div><p>Those two lines mean the server and the client both started. If they do not appear, see <a href="/Keel-Docs/reference/troubleshooting">Troubleshooting</a>.</p><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>Client code lives in <code>ReplicatedFirst</code>, not in <code>StarterPlayerScripts</code>. Scripts in <code>StarterPlayerScripts</code> are cloned into each player when the game runs, so clicking an error opens the clone and edits made there are lost. Modules in <code>ReplicatedFirst</code> are not cloned, so errors open the real source.</p></div><h2 id="optional-place-settings" tabindex="-1">Optional place settings <a class="header-anchor" href="#optional-place-settings" aria-label="Permalink to &quot;Optional place settings&quot;">​</a></h2><p>The attributes the plugin creates are optional: each has a default written in its script, so the game works if you never set them. See <a href="/Keel-Docs/guides/tooling#place-attributes">Tooling and hooks</a>.</p>`,28)])])}const g=t(i,[["render",n]]);export{u as __pageData,g as default};
